char **T9(char *num, char **words, int wordsSize, int *returnSize) {
  const char *map[] = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
  char **res = (char **)malloc(sizeof(char *) * wordsSize);
  *returnSize = 0;
  int numLen = strlen(num);
  for (int i = 0; i < wordsSize; i++) {
    int wl = strlen(words[i]);
    if (wl != numLen) continue;
    bool ok = true;
    for (int j = 0; j < wl; j++) {
      const char *letters = map[num[j] - '0'];
      if (strchr(letters, words[i][j]) == NULL) {
        ok = false;
        break;
      }
    }
    if (ok) res[(*returnSize)++] = words[i];
  }
  return res;
}

class Solution {
public:
  vector<string> T9(string num, vector<string> &words) {
    const vector<string> map = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
    vector<string> res;
    for (const string &w : words) {
      if (w.size() != num.size()) continue;
      bool ok = true;
      for (size_t j = 0; j < w.size(); j++) {
        if (map[num[j] - '0'].find(w[j]) == string::npos) {
          ok = false;
          break;
        }
      }
      if (ok) res.push_back(w);
    }
    return res;
  }
};

func T9(num string, words []string) []string {
	mapping := []string{"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"}
	res := []string{}
	for _, w := range words {
		if len(w) != len(num) {
			continue
		}
		ok := true
		for j := 0; j < len(w); j++ {
			if !strings.Contains(mapping[num[j]-'0'], string(w[j])) {
				ok = false
				break
			}
		}
		if ok {
			res = append(res, w)
		}
	}
	return res
}

class Solution {
  public List<String> T9(String num, String[] words) {
    String[] map = { "", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz" };
    List<String> res = new ArrayList<>();
    for (String w : words) {
      if (w.length() != num.length()) continue;
      boolean ok = true;
      for (int j = 0; j < w.length(); j++) {
        if (map[num.charAt(j) - '0'].indexOf(w.charAt(j)) < 0) {
          ok = false;
          break;
        }
      }
      if (ok) res.add(w);
    }
    return res;
  }
}

class Solution:
    def T9(self, num: str, words: List[str]) -> List[str]:
        mapping = ["", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"]
        res = []
        for w in words:
            if len(w) != len(num):
                continue
            if all(w[j] in mapping[int(num[j])] for j in range(len(w))):
                res.append(w)
        return res

impl Solution {
  pub fn t9(num: String, words: Vec<String>) -> Vec<String> {
    let mapping = ["", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"];
    let n = num.as_bytes();
    let mut res = vec![];
    for w in words {
      if w.len() != n.len() {
        continue;
      }
      let wb = w.as_bytes();
      let mut ok = true;
      for j in 0..wb.len() {
        let letters = mapping[(n[j] - b'0') as usize];
        if !letters.contains(wb[j] as char) {
          ok = false;
          break;
        }
      }
      if ok {
        res.push(w);
      }
    }
    res
  }
}

const T9 = (num: string, words: string[]): string[] => {
  const mapping = ['', '', 'abc', 'def', 'ghi', 'jkl', 'mno', 'pqrs', 'tuv', 'wxyz'];
  const res: string[] = [];
  for (const w of words) {
    if (w.length !== num.length) continue;
    let ok = true;
    for (let j = 0; j < w.length; j++) {
      if (!mapping[Number(num[j])].includes(w[j])) {
        ok = false;
        break;
      }
    }
    if (ok) res.push(w);
  }
  return res;
};
